async function runSuperAdminAccessMutation(req, res, {
  entityType,
  entityLabel,
  actionType,
  successMessage,
  selectSnapshot,
  mutate,
  preventSelfTarget = false
}) {
  let connection;

  try {
    const access = await requireSuperAdminAccess(req, res);
    if (!access) return;

    const targetId = Number(req.params.id || 0);
    if (!targetId) {
      return res.status(400).json({
        success: false,
        message: `${entityLabel} id is required`
      });
    }

    if (preventSelfTarget && Number(access.actingUserId || 0) === targetId) {
      return res.status(400).json({
        success: false,
        message: "SuperAdmin cannot disable, delete, or force logout themselves"
      });
    }

    const reasonResult = getRequiredReason(req);
    if (!reasonResult.ok) {
      return res.status(400).json({
        success: false,
        message: reasonResult.message
      });
    }

    connection = await pool.getConnection();
    await connection.beginTransaction();

    const before = await selectSnapshot(connection, targetId);
    if (!before) {
      await connection.rollback();
      return res.status(404).json({
        success: false,
        message: `${entityLabel} not found`
      });
    }

    if (entityType === "USER" && isSuperAdminUser(before)) {
      await connection.rollback();
      return res.status(400).json({
        success: false,
        message: "SuperAdmin accounts cannot be managed from access-control actions."
      });
    }

    const mutationResult = await mutate(connection, {
      targetId,
      reason: reasonResult.reason,
      access,
      before
    });

    if (mutationResult?.ok === false) {
      await connection.rollback();
      return res.status(mutationResult.status || 400).json({
        success: false,
        message: mutationResult.message || "Access update failed"
      });
    }

    const after = await selectSnapshot(connection, targetId);

    await logActivitySafe(connection, req, access, {
      companyId: entityType === "COMPANY" ? targetId : before.company_id ?? null,
      userId: entityType === "USER" ? targetId : null,
      actionType,
      entityType,
      entityId: String(targetId),
      moduleName: "superadmin-access",
      status: "success",
      message: successMessage,
      beforeData: before,
      afterData: after,
      metadata: {
        reason: reasonResult.reason
      }
    });

    await connection.commit();

    return res.json({
      success: true,
      message: successMessage,
      [entityType === "COMPANY" ? "company" : "user"]: after
    });
  } catch (error) {
    if (connection) {
      try {
        await connection.rollback();
      } catch (_) {}
    }

    console.error(`${actionType || "SuperAdmin access mutation"} error:`, error);
    return res.status(500).json({
      success: false,
      message: "Access update failed",
      error: getErrorDetail(error)
    });
  } finally {
    if (connection) connection.release();
  }
}

async function testDbConnection() {
  let conn = null;
  try {
    conn = await pool.getConnection();
    await conn.ping();
  } catch (error) {
    const diagnostic = getMysqlConnectionDiagnostic(error);
    const safeError = new Error(diagnostic);
    safeError.cause = error;
    throw safeError;
  } finally {
    if (conn) conn.release();
  }
}

async function requireActiveBranchForCompany(connection, companyId, branchId) {
  const cleanBranchId = Number(branchId || 0);
  if (!cleanBranchId) return { ok: true, branch: null };

  const branch = await getBranchForCompany(connection, companyId, cleanBranchId);
  if (!branch) {
    return { ok: false, status: 404, message: "Branch not found" };
  }

  if (String(branch.status || "ACTIVE").trim().toUpperCase() !== "ACTIVE") {
    return { ok: false, status: 400, message: "Branch is inactive" };
  }

  return { ok: true, branch };
}

function getItemSourceBarcodes(item = {}) {
  const sources = [
    item.barcode,
    item.sourceBarcode,
    item.source_barcode,
    ...(Array.isArray(item.sourceBarcodes) ? item.sourceBarcodes : []),
    ...(Array.isArray(item.source_barcodes) ? item.source_barcodes : []),
    ...(Array.isArray(item.barcodes) ? item.barcodes : [])
  ];
  return [...new Set(sources.map((barcode) => String(barcode || "").trim()).filter(Boolean))];
}

async function tableExists(tableName) {
  const [rows] = await pool.query(
    `
    SELECT COUNT(*) AS total
    FROM information_schema.tables
    WHERE table_schema = DATABASE()
      AND table_name = ?
    `,
    [tableName]
  );
  return Number(rows[0]?.total || 0) > 0;
}

async function columnExists(tableName, columnName) {
  const [rows] = await pool.query(
    `
    SELECT COUNT(*) AS total
    FROM information_schema.columns
    WHERE table_schema = DATABASE()
      AND table_name = ?
      AND column_name = ?
    `,
    [tableName, columnName]
  );
  return Number(rows[0]?.total || 0) > 0;
}

async function addColumnIfMissing(tableName, columnName, definitionSql) {
  const exists = await columnExists(tableName, columnName);
  if (!exists) {
    await pool.query(`ALTER TABLE ${tableName} ADD COLUMN ${columnName} ${definitionSql}`);
    console.log(`Column added: ${tableName}.${columnName}`);
  }
}

async function addColumnIfMissingSafe(tableName, columnName, definitionSql) {
  try {
    await addColumnIfMissing(tableName, columnName, definitionSql);
    return true;
  } catch (error) {
    console.warn(`Column skipped safely: ${tableName}.${columnName} (${error?.code || error?.message || "unknown error"})`);
    return false;
  }
}

async function addGeneratedColumnIfMissingSafe(tableName, columnName, definitionSql) {
  const exists = await columnExists(tableName, columnName);
  if (exists) return true;
  try {
    await pool.query(`ALTER TABLE ${tableName} ADD COLUMN ${columnName} ${definitionSql}`);
    console.log(`Generated column added: ${tableName}.${columnName}`);
    return true;
  } catch (error) {
    console.warn(`Generated column skipped: ${tableName}.${columnName} (${error?.code || error?.message || "unknown error"})`);
    return false;
  }
}

async function indexExists(tableName, indexName) {
  const [rows] = await pool.query(
    `
    SELECT COUNT(*) AS total
    FROM information_schema.statistics
    WHERE table_schema = DATABASE()
      AND table_name = ?
      AND index_name = ?
    `,
    [tableName, indexName]
  );
  return Number(rows[0]?.total || 0) > 0;
}

async function addIndexIfMissing(tableName, indexName, definitionSql) {
  const exists = await indexExists(tableName, indexName);
  if (!exists) {
    try {
      await pool.query(`ALTER TABLE ${tableName} ADD INDEX ${indexName} ${definitionSql}`);
      console.log(`Index added: ${tableName}.${indexName}`);
    } catch (error) {
      if (error?.code !== "ER_DUP_KEYNAME") {
        throw error;
      }
    }
  }
}

async function addIndexIfMissingSafe(tableName, indexName, definitionSql) {
  try {
    await addIndexIfMissing(tableName, indexName, definitionSql);
    return true;
  } catch (error) {
    console.warn(`Index skipped safely: ${tableName}.${indexName} (${error?.code || error?.message || "unknown error"})`);
    return false;
  }
}

async function addUniqueIndexIfMissing(tableName, indexName, definitionSql) {
  const exists = await indexExists(tableName, indexName);
  if (!exists) {
    try {
      await pool.query(`ALTER TABLE ${tableName} ADD UNIQUE INDEX ${indexName} ${definitionSql}`);
      console.log(`Unique index added: ${tableName}.${indexName}`);
    } catch (error) {
      if (error?.code !== "ER_DUP_KEYNAME") {
        throw error;
      }
    }
  }
}

function isDuplicateKeyError(error) {
  return error?.code === "ER_DUP_ENTRY" || Number(error?.errno || 0) === 1062;
}

