app.get("/api/dashboard", authMiddleware, async (req, res) => {
  try {
    const access = await resolveBranchAccessContext(req, {
      requireCompanyScope: false
    });

    if (!access.ok) {
      return sendAccessError(res, access);
    }

    const companyId = access.companyScope;
    const branchScope = await resolveSalesReadBranchScope(pool, req, access, { action: "DASHBOARD_SALES_READ" });
    if (!branchScope.ok) {
      return res.status(branchScope.status || 403).json({
        success: false,
        message: branchScope.message || "Branch access denied"
      });
    }
    await auditBranchPersistenceBackfillWarning(pool, req, access, branchScope, { action: "DASHBOARD_SALES_READ" });

    const sellableStockFilter = getSellableFinishedStockWhereSql();
    const stockWhereParts = ["1 = 1"];
    const stockParams = [];
    if (companyId !== null) {
      stockWhereParts.push("company_id = ?");
      stockParams.push(companyId);
    }
    if (branchScope.isBranchFiltered) {
      stockWhereParts.push("current_branch_id = ?");
      stockParams.push(branchScope.branchId);
    }
    const stockWhere = `WHERE ${stockWhereParts.join(" AND ")} ${sellableStockFilter}`;

    const salesWhereParts = ["1 = 1"];
    const salesWhereParams = [];
    if (companyId !== null) {
      salesWhereParts.push("sh.company_id = ?");
      salesWhereParams.push(companyId);
    }
    appendSalesBranchScope(salesWhereParts, salesWhereParams, branchScope, { saleAlias: "sh" });
    const salesBranchTotals = buildSalesBranchTotalsJoin(branchScope);
    const salesWhere = `WHERE ${salesWhereParts.join(" AND ")}`;
    const salesParams = [...salesBranchTotals.params, ...salesWhereParams];

    const [stockSummary] = await pool.query(
      `
      SELECT COUNT(*) AS total_items, COALESCE(SUM(weight), 0) AS total_weight
      FROM stock
      ${stockWhere}
      `,
      stockParams
    );

    const [soldSummary] = await pool.query(
      `
      SELECT COUNT(*) AS sold_items
      FROM stock
      ${stockWhere}
        AND status = 'SOLD'
      `,
      stockParams
    );

    const [inStockSummary] = await pool.query(
      `
      SELECT COUNT(*) AS in_stock_items
      FROM stock
      ${stockWhere}
        AND status = 'IN_STOCK'
      `,
      stockParams
    );

    const [salesSummary] = await pool.query(
      `
      SELECT
        COUNT(*) AS total_sales,
        ${branchScope.isBranchFiltered
          ? "COALESCE(SUM(COALESCE(branch_totals.branch_total_amount, 0)), 0)"
          : "COALESCE(SUM(sh.total_amount), 0)"} AS total_sales_amount
      FROM sales_history sh
      ${salesBranchTotals.sql}
      ${salesWhere}
      `,
      salesParams
    );

    const itemCommercialWhereParts = ["COALESCE(si.is_deleted, 0) = 0"];
    const itemCommercialParams = [];
    if (companyId !== null) {
      itemCommercialWhereParts.push("si.company_id = ?");
      itemCommercialParams.push(companyId);
    }
    appendSalesItemBranchScope(itemCommercialWhereParts, itemCommercialParams, branchScope, { itemAlias: "si" });
    const [salesCommercialSummary] = await pool.query(
      `
      SELECT
        COALESCE(SUM(COALESCE(NULLIF(si.actual_weight, 0), si.weight, 0)), 0) AS total_actual_weight,
        COALESCE(SUM(COALESCE(NULLIF(si.billable_weight, 0), si.weight, 0)), 0) AS total_billable_weight,
        COALESCE(SUM(COALESCE(NULLIF(si.lamination_gain_weight, 0), GREATEST(COALESCE(NULLIF(si.billable_weight, 0), si.weight, 0) - COALESCE(NULLIF(si.actual_weight, 0), si.weight, 0), 0), 0)), 0) AS total_lamination_gain_weight,
        COALESCE(SUM(COALESCE(NULLIF(si.lamination_gain_weight, 0), GREATEST(COALESCE(NULLIF(si.billable_weight, 0), si.weight, 0) - COALESCE(NULLIF(si.actual_weight, 0), si.weight, 0), 0), 0) * COALESCE(NULLIF(si.selling_rate_per_gram, 0), 0)), 0) AS estimated_commercial_gain_value
      FROM sales_items si
      WHERE ${itemCommercialWhereParts.join(" AND ")}
      `,
      itemCommercialParams
    );

    const [recentInvoices] = await pool.query(
      `
      SELECT
        sh.invoice_number,
        sh.customer_name,
        ${branchScope.isBranchFiltered
          ? "COALESCE(branch_totals.branch_total_amount, 0)"
          : "sh.total_amount"} AS total_amount,
        sh.invoice_date,
        sh.created_at,
        sh.company_id
      FROM sales_history sh
      ${salesBranchTotals.sql}
      ${salesWhere}
      ORDER BY sh.id DESC
      LIMIT 8
      `,
      salesParams
    );

    const [recentStock] = await pool.query(
      `
      SELECT barcode, product_name, category, source, lot_number, size, weight, status, company_id, created_at
      FROM stock
      ${stockWhere}
      ORDER BY id DESC
      LIMIT 8
      `,
      stockParams
    );

    const branchSummaryParams = [];
    const branchSummaryWhereParts = ["1 = 1"];
    if (companyId !== null) {
      branchSummaryWhereParts.push("s.company_id = ?");
      branchSummaryParams.push(companyId);
    }
    appendBranchScopeFilter(branchSummaryWhereParts, branchSummaryParams, branchScope, { alias: "s" });

    const [branchStockSummary] = await pool.query(
      `
      SELECT
        s.current_branch_id,
        b.branch_code,
        b.branch_name,
        COUNT(*) AS stock_count,
        COALESCE(SUM(CASE WHEN UPPER(COALESCE(s.status, 'IN_STOCK')) = 'IN_STOCK'
          AND UPPER(COALESCE(NULLIF(TRIM(s.stock_state), ''), s.status, 'IN_STOCK')) = 'IN_STOCK'
          THEN s.weight ELSE 0 END), 0) AS stock_weight,
        SUM(CASE WHEN UPPER(COALESCE(NULLIF(TRIM(s.stock_state), ''), s.status, 'IN_STOCK')) = 'IN_TRANSIT' THEN 1 ELSE 0 END) AS in_transit_count,
        COALESCE(SUM(CASE WHEN UPPER(COALESCE(NULLIF(TRIM(s.stock_state), ''), s.status, 'IN_STOCK')) = 'IN_TRANSIT' THEN s.weight ELSE 0 END), 0) AS in_transit_weight
      FROM stock s
      LEFT JOIN branches b
        ON b.id = s.current_branch_id
       AND b.company_id = s.company_id
      WHERE ${branchSummaryWhereParts.join(" AND ")}
        AND UPPER(COALESCE(s.status, 'IN_STOCK')) <> 'DELETED'
      GROUP BY s.current_branch_id, b.branch_code, b.branch_name
      ORDER BY b.branch_name ASC, s.current_branch_id ASC
      `,
      branchSummaryParams
    );

    const [branchSalesSummary] = await pool.query(
      `
      SELECT
        s.current_branch_id,
        b.branch_code,
        b.branch_name,
        COUNT(DISTINCT si.id) AS sold_items,
        COALESCE(SUM(si.weight), 0) AS sold_weight
      FROM sales_items si
      INNER JOIN stock s
        ON s.company_id = si.company_id
       AND UPPER(TRIM(s.barcode)) = UPPER(TRIM(si.barcode))
      LEFT JOIN branches b
        ON b.id = s.current_branch_id
       AND b.company_id = s.company_id
      WHERE ${branchSummaryWhereParts.join(" AND ")}
      GROUP BY s.current_branch_id, b.branch_code, b.branch_name
      ORDER BY b.branch_name ASC, s.current_branch_id ASC
      LIMIT 200
      `,
      branchSummaryParams
    );

    const returnSummary = await getReturnSummaryRows(companyId);

    return res.json({
      success: true,
      totalStock: Number(stockSummary[0]?.total_items || 0),
      totalWeight: Number(stockSummary[0]?.total_weight || 0),
      soldItems: Number(soldSummary[0]?.sold_items || 0),
      availableItems: Number(inStockSummary[0]?.in_stock_items || 0),
      normalReturns: returnSummary.returnToStockCount,
      damagedReturns: returnSummary.damagedReturnCount,
      totalSales: Number(salesSummary[0]?.total_sales || 0),
      totalSalesAmount: Number(salesSummary[0]?.total_sales_amount || 0),
      totalActualWeight: Number(salesCommercialSummary[0]?.total_actual_weight || 0),
      totalBillableWeight: Number(salesCommercialSummary[0]?.total_billable_weight || 0),
      totalLaminationGainWeight: Number(salesCommercialSummary[0]?.total_lamination_gain_weight || 0),
      estimatedCommercialGainValue: Number(salesCommercialSummary[0]?.estimated_commercial_gain_value || 0),
      recentInvoices,
      recentStock,
      recentReturns: returnSummary.recentReturns,
      branchScope: getBranchScopeResponse(branchScope),
      branchStockSummary,
      branchSalesSummary
    });
  } catch (error) {
    console.error("Dashboard error:", error);
    return res.status(500).json({ success: false, message: "Dashboard fetch failed" });
  }
});

