function createStickerBulkError(message, status = 400, details = null) {
  const error = new Error(message);
  error.status = status;
  error.statusCode = status;
  error.isStickerBulkError = true;
  error.details = details;
  return error;
}

function normalizeStickerSaveItem(item = {}, index = 0) {
  const rowLabel = `Sticker row ${index + 1}`;
  const serial = String(item.serial ?? "").trim();
  const productName = String(item.productName ?? item.product_name ?? "").trim();
  const purity = String(item.purity ?? "").trim();
  const sku = String(item.sku ?? "").trim();
  const mm = String(item.mm ?? "").trim();
  const size = String(item.size ?? "").trim();
  const lot = String(item.lot ?? item.lot_number ?? "").trim();
  const metalType = String(item.metalType ?? item.metal_type ?? "").trim();
  const processType = String(item.processType ?? item.process_type ?? "").trim();
  const barcode = String(item.barcode ?? "").trim();

  if (!serial || !productName || !purity || !sku || !size || !lot || !barcode || !hasProvidedValue(item.weight)) {
    throw createStickerBulkError(`${rowLabel}: Serial, product, purity, SKU, size, weight, lot, and barcode are required`);
  }

  const parsedWeight = parseRequiredNumber(item.weight, `${rowLabel} weight`);
  if (!parsedWeight.ok || parsedWeight.value <= 0) {
    throw createStickerBulkError(`${rowLabel}: ${parsedWeight.ok ? "Sticker weight must be greater than zero" : parsedWeight.message}`);
  }

  const qtyProvided = hasProvidedValue(item.qty);
  const parsedQty = parseOptionalNumber(item.qty, `${rowLabel} quantity`, 1);
  if (!parsedQty.ok || parsedQty.value <= 0) {
    throw createStickerBulkError(`${rowLabel}: ${parsedQty.ok ? "Sticker quantity must be greater than zero" : parsedQty.message}`);
  }

  return {
    index,
    rowLabel,
    serial,
    productName,
    purity,
    sku,
    mm,
    size,
    weight: Number(format3(parsedWeight.value)),
    qty: parsedQty.value,
    qtyProvided,
    lot,
    metalType,
    processType,
    barcode,
    normalizedBarcode: normalizeBarcodeForComparison(barcode)
  };
}

async function validateStickerSaveItemAgainstStock(connection, companyId, item, { req = null, access = null } = {}) {
  await ensureSingleStockBarcode(companyId, item.barcode, connection);
  await assertActiveBarcodeAvailable(companyId, {
    barcode: item.barcode,
    status: "IN_STOCK",
    stock_state: "IN_STOCK",
    source: "",
    process_type: item.processType,
    category: "",
    product_name: item.productName,
    invoice_number: "",
    deleted_at: null
  }, {
    db: connection,
    req,
    access,
    context: "ADD_STICKERS_BULK"
  });

  const [dupLotSerial] = await connection.query(
    `
    SELECT id FROM stock
    WHERE lot_number = ?
      AND serial = ?
      AND company_id = ?
      AND UPPER(COALESCE(status, 'IN_STOCK')) = 'IN_STOCK'
    LIMIT 1
    FOR UPDATE
    `,
    [item.lot, item.serial, companyId]
  );

  if (dupLotSerial.length > 0) {
    throw createStickerBulkError(`${item.rowLabel}: Serial ${item.serial} already exists in lot ${item.lot}`);
  }

}

async function insertStickerStockRow(connection, item, {
  companyId,
  userId,
  branchId,
  processLot,
  stickerAllowance = null
}) {
  const isManualStickerLot = isManualProcessLot(processLot);
  const commercialWeights = getStickerCommercialWeights(item, stickerAllowance);

  await connection.query(
    `
    INSERT INTO stock (
      serial,
      product_name,
      purity,
      sku,
      mm,
      size,
      weight,
      actual_weight,
      billable_weight,
      lamination_gain_weight,
      qty,
      lot_number,
      barcode,
      metal_type,
      process_type,
      source,
      manual_lot_id,
      status,
      stock_state,
      current_branch_id,
      company_id,
      created_by,
      deleted_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `,
    [
      item.serial,
      item.productName,
      item.purity,
      item.sku,
      item.mm,
      item.size,
      item.weight,
      commercialWeights.actualWeight,
      commercialWeights.billableWeight,
      commercialWeights.laminationGainWeight,
      item.qty,
      item.lot,
      item.barcode,
      item.metalType,
      item.processType,
      isManualStickerLot ? "MANUAL_ENTRY" : "",
      isManualStickerLot ? Number(processLot.id || 0) || null : null,
      "IN_STOCK",
      "IN_STOCK",
      branchId,
      companyId,
      userId,
      null
    ]
  );

  const stockId = Number(insertResult?.insertId || 0) || null;
  await appendBarcodeLifecycleEvent(connection, {
    companyId,
    barcode: item.barcode,
    stockId,
    lotNo: item.lot,
    serial: item.serial,
    processLotId: isManualStickerLot ? null : processLot?.id,
    branchId,
    eventType: BARCODE_LIFECYCLE_EVENT_TYPES.STICKER_CREATED,
    eventTitle: "Sticker Created",
    eventDescription: "Sticker stock row created",
    eventPayload: {
      productName: item.productName,
      sku: item.sku,
      purity: item.purity,
      size: item.size,
      weight: item.weight,
      actualWeight: commercialWeights.actualWeight,
      billableWeight: commercialWeights.billableWeight,
      laminationGainWeight: commercialWeights.laminationGainWeight,
      qty: item.qty,
      metalType: item.metalType,
      processType: item.processType,
      source: isManualStickerLot ? "MANUAL_ENTRY" : "PROCESS_STICKER"
    },
    sourceTable: "stock",
    sourceId: stockId,
    createdBy: userId
  });

  return stockId;
}

