app.get("/getInvoiceItems/:invoiceNumber", authMiddleware, async (req, res) => {
  try {
    const invoiceNumber = String(req.params.invoiceNumber || "").trim();
    const access = await resolveBranchAccessContext(req, {
      requireCompanyScope: true
    });

    if (!access.ok) {
      return sendAccessError(res, access);
    }

    const companyId = access.companyScope;
    const branchScope = await resolveSalesReadBranchScope(pool, req, access, { action: "GET_INVOICE_ITEMS" });
    if (!branchScope.ok) {
      return res.status(branchScope.status || 403).json({
        success: false,
        message: branchScope.message || "Branch access denied"
      });
    }
    await auditBranchPersistenceBackfillWarning(pool, req, access, branchScope, { action: "GET_INVOICE_ITEMS" });

    const [invoiceItemCountRows] = await pool.query(
      `
      SELECT COUNT(*) AS total_items
      FROM sales_items
      WHERE invoice_number = ?
        AND COALESCE(is_deleted, 0) = 0
        AND company_id = ?
      `,
      [invoiceNumber, companyId]
    );
    const invoiceItemCount = Number(invoiceItemCountRows?.[0]?.total_items || 0);

    const itemWhereParts = [
      "si.invoice_number = ?",
      "COALESCE(si.is_deleted, 0) = 0",
      "si.company_id = ?"
    ];
    const itemParams = [invoiceNumber, companyId];
    appendSalesItemBranchScope(itemWhereParts, itemParams, branchScope, { itemAlias: "si" });

    const [items] = await pool.query(
      `
      SELECT
        si.*,
        COALESCE(NULLIF(si.actual_weight, 0), si.weight, 0) AS effective_actual_weight,
        COALESCE(NULLIF(si.billable_weight, 0), si.weight, 0) AS effective_billable_weight,
        COALESCE(NULLIF(si.lamination_gain_weight, 0), GREATEST(COALESCE(NULLIF(si.billable_weight, 0), si.weight, 0) - COALESCE(NULLIF(si.actual_weight, 0), si.weight, 0), 0), 0) AS effective_lamination_gain_weight
      FROM sales_items si
      WHERE ${itemWhereParts.join(" AND ")}
      ORDER BY si.id DESC
      `,
      itemParams
    );

    if (branchScope.isBranchFiltered && invoiceItemCount > 0 && items.length === 0) {
      await auditBranchReportAccessDenied(pool, req, access, {
        action: "GET_INVOICE_ITEMS",
        invoiceNumber,
        requestedBranchId: branchScope.branchId,
        message: "Invoice belongs to another branch"
      });
      return res.status(403).json({
        success: false,
        message: "You cannot access another branch invoice"
      });
    }

    return res.json({
      success: true,
      items
    });
  } catch (error) {
    console.error("Invoice items error:", error);
    return res.status(500).json({
      success: false,
      message: "Invoice items fetch failed"
    });
  }
});

app.put("/process/lots/:lotNo/complete", authMiddleware, checkRole(["SUPERADMIN", "OWNER", "STAFF"]), async (req, res) => {
  let connection;

  try {
    const access = await resolveAccessContext(req, {
      requireActingUser: true,
      requireCompanyScope: true,
      allowSuperAdminAll: true
    });

    if (!access.ok) {
      return sendAccessError(res, access);
    }

    const lotNo = normalizeProcessLotNo(req.params.lotNo || req.body.lotNo || req.body.lot_no);
    const workCategory = normalizeWorkCategory(req.query.workCategory || req.query.work_category || req.body.workCategory || req.body.work_category || "REGULAR_SANKHA");
    if (!lotNo) {
      return res.status(400).json({
        success: false,
        message: "lotNo is required"
      });
    }

    connection = await pool.getConnection();
    await connection.beginTransaction();

    const processLot = await getProcessLotForSteps(connection, access.companyScope, lotNo, workCategory);
    if (!processLot) {
      await connection.rollback();
      return res.status(404).json({
        success: false,
        message: "Process lot not found"
      });
    }

    if (isManualProcessLot(processLot)) {
      await connection.rollback();
      return res.status(400).json({
        success: false,
        message: "Manual lots are not available in the process workflow yet"
      });
    }

    const destination = getWorkCategoryDestination(workCategory);
    const openStep = await getOpenProcessStep(connection, access.companyScope, processLot.id);
    if (openStep) {
      await connection.rollback();
      return res.status(400).json({
        success: false,
        message: "Complete all OPEN process steps before completing the lot"
      });
    }

    const finalStep = await getLastCompletedProcessStep(connection, access.companyScope, processLot.id);
    if (!finalStep) {
      await connection.rollback();
      return res.status(400).json({
        success: false,
        message: "At least one completed process step is required before completing the lot"
      });
    }

    if (toNumber(finalStep.output_weight) <= 0) {
      await connection.rollback();
      return res.status(400).json({
        success: false,
        message: "Latest completed process step must have output weight greater than zero before completing the lot"
      });
    }

    const [negativeLossRows] = await connection.query(
      `
      SELECT id, step_no, process_name, loss_weight
      FROM process_steps
      WHERE company_id = ?
        AND process_lot_id = ?
        AND status = 'COMPLETED'
        AND COALESCE(loss_weight, 0) < 0
      LIMIT 1
      `,
      [access.companyScope, processLot.id]
    );

    if (negativeLossRows.length) {
      const badStep = negativeLossRows[0];
      await connection.rollback();
      return res.status(400).json({
        success: false,
        message: `Process step ${badStep.step_no || badStep.id} has negative loss. Correct the process loss before completing the lot.`
      });
    }

    if (isOutsideKarigarCategory(workCategory)) {
      const [pendingOutsideRows] = await connection.query(
        `
        SELECT COALESCE(SUM(pending_weight), 0) AS pending_weight
        FROM outside_karigar_ledger
        WHERE company_id = ?
          AND process_lot_id = ?
          AND work_category = ?
          AND COALESCE(pending_weight, 0) > 0
          AND UPPER(COALESCE(status, 'ISSUED')) IN ('ISSUED', 'PARTIAL_RECEIVED')
        `,
        [access.companyScope, processLot.id, workCategory]
      );
      const pendingOutsideWeight = toNumber(pendingOutsideRows[0]?.pending_weight);

      if (pendingOutsideWeight > 0) {
        await connection.rollback();
        return res.status(400).json({
          success: false,
          message: `Cannot complete this lot. Outside karigar pending weight is ${pendingOutsideWeight.toFixed(3)}g. Receive pending work first.`
        });
      }
    }

    const templateContext = await getProcessTemplateStepsForLot(connection, access.companyScope, processLot);
    const templateSteps = templateContext.steps || [];

    if (templateSteps.length) {
      const [completedStepRows] = await connection.query(
        `
        SELECT process_name
        FROM process_steps
        WHERE company_id = ?
          AND process_lot_id = ?
          AND status = 'COMPLETED'
        ORDER BY step_no ASC, id ASC
        `,
        [access.companyScope, processLot.id]
      );
      const completedNameSet = new Set(
        completedStepRows
          .map((row) => normalizeTemplateStepName(row.process_name))
          .filter(Boolean)
      );
      const missingTemplateStep = templateSteps.find((step) => {
        return !completedNameSet.has(normalizeTemplateStepName(step.stepName));
      });
      const finalTemplateStep = templateSteps[templateSteps.length - 1];
      const finalStepReached = completedNameSet.has(normalizeTemplateStepName(finalTemplateStep?.stepName));

      if (missingTemplateStep || !finalStepReached) {
        await connection.rollback();
        return res.status(400).json({
          success: false,
          message: `Process template is not complete. Complete final step "${finalTemplateStep?.stepName || "Final Step"}" before completing the lot.`
        });
      }
    }

    await connection.query(
      `
      UPDATE process_lots
      SET status = 'COMPLETED',
          completed_at = NOW(),
          completed_by = ?,
          updated_at = NOW()
      WHERE id = ?
      `,
      [access.actingUserId || null, processLot.id]
    );

    const directStockItem = destination === "STOCK"
      ? await moveCompletedProcessLotToStock(
        connection,
        access.companyScope,
        processLot,
        finalStep,
        access.actingUserId || null
      )
      : null;

    const [savedRows] = await connection.query(
      `
      SELECT *
      FROM process_lots
      WHERE id = ?
      LIMIT 1
      `,
      [processLot.id]
    );

    await connection.commit();

    return res.json({
      success: true,
      message: destination === "STOCK"
        ? "Lot completed. Added to Stock."
        : "Lot completed. Ready for Sticker.",
      destination,
      directStockItem,
      lot: savedRows.length ? normalizeProcessLotRow(savedRows[0]) : null
    });
  } catch (error) {
    if (connection) await connection.rollback();
    console.error("Complete process lot error:", error);
    return res.status(500).json({
      success: false,
      message: "Process lot completion failed",
      error: getErrorDetail(error)
    });
  } finally {
    if (connection) connection.release();
  }
});

app.get("/sales-history/payment-history/:invoiceNumber", authMiddleware, async (req, res) => {
  try {
    const invoiceNumber = String(req.params.invoiceNumber || "").trim();
    const access = await resolveAccessContext(req, {
      requireActingUser: true,
      requireCompanyScope: true,
      allowSuperAdminAll: false
    });

    if (!access.ok) {
      return sendAccessError(res, access);
    }

    if (!invoiceNumber) {
      return res.status(400).json({
        success: false,
        message: "Invoice number is required"
      });
    }

    const companyId = access.companyScope;

    const [rows] = await pool.query(
      `
      SELECT
        tm.id,
        tm.voucher_no,
        tm.voucher_date,
        tm.payment_mode,
        COALESCE(ts.cash_amount, 0) AS amount,
        COALESCE(tm.note, tm.remarks, '') AS note
      FROM invoice_transaction_link itl
      INNER JOIN transaction_master tm ON tm.id = itl.transaction_id
      LEFT JOIN transaction_settlements ts ON ts.transaction_id = tm.id
      WHERE itl.company_id = ?
        AND itl.invoice_no = ?
        AND tm.transaction_type = 'PAYMENT_RECEIVED'
      ORDER BY tm.id DESC
      `,
      [companyId, invoiceNumber]
    );

    return res.json({
      success: true,
      history: rows.map((row) => ({
        id: row.id,
        voucherNo: row.voucher_no || "",
        paymentDate: row.voucher_date || "",
        paymentMode: row.payment_mode || "",
        amount: toNumber(row.amount),
        note: String(row.note || "").trim()
      }))
    });
  } catch (error) {
    console.error("Sales history payment history error:", error);
    return res.status(500).json({
      success: false,
      message: "Payment history fetch failed"
    });
  }
});

app.post("/sales-history/update-payment", authMiddleware, checkRole(["SUPERADMIN", "OWNER", "ACCOUNTS"]), async (req, res) => {
  let connection;

  try {
    const access = await resolveAccessContext(req, {
      requireActingUser: true,
      requireCompanyScope: true,
      allowSuperAdminAll: false
    });

    if (!access.ok) {
      return sendAccessError(res, access);
    }

    const companyId = access.companyScope;
    const createdBy = access.actingUserId ?? getRequestedUserId(req);
    const invoiceNumber = String(req.body.invoiceNo || req.body.invoice_number || "").trim();
    const paymentMode = String(req.body.paymentMode || req.body.payment_mode || "").trim();
    const note = String(req.body.note || "").trim();
    const paymentAmount = toNumber(req.body.amount);
    const paymentDate = getTodayDateOnly();

    if (!invoiceNumber) {
      return res.status(400).json({
        success: false,
        message: "Invoice number is required"
      });
    }

    if (!(paymentAmount > 0)) {
      return res.status(400).json({
        success: false,
        message: "Payment amount must be greater than zero"
      });
    }

    connection = await pool.getConnection();
    await connection.beginTransaction();

    const [salesRows] = await connection.query(
      `
      SELECT *
      FROM sales_history
      WHERE invoice_number = ? AND company_id = ?
      ORDER BY id DESC
      LIMIT 1
      `,
      [invoiceNumber, companyId]
    );

    const saleRow = salesRows[0];
    if (!saleRow) {
      await connection.rollback();
      return res.status(404).json({
        success: false,
        message: "Sale record not found"
      });
    }

    if (Number(saleRow.is_deleted || 0) === 1) {
      await connection.rollback();
      return res.status(400).json({
        success: false,
        message: "Cannot update payment for deleted sale"
      });
    }

    const currentPaid = toNumber(saleRow.paid_amount);
    const currentDue = toNumber(saleRow.due_amount);
    if (currentDue <= 0.009) {
      await connection.rollback();
      return res.status(400).json({
        success: false,
        message: "This invoice is already fully paid"
      });
    }

    if (paymentAmount - currentDue > 0.009) {
      await connection.rollback();
      return res.status(400).json({
        success: false,
        message: "Payment amount cannot exceed due amount"
      });
    }

    const saleTxn = await findExistingSaleInvoiceTransaction(connection, companyId, invoiceNumber);
    if (!saleTxn?.id) {
      await connection.rollback();
      return res.status(400).json({
        success: false,
        message: "Original sale transaction not found"
      });
    }

    const [saleTxnRows] = await connection.query(
      `
      SELECT id, voucher_no, party_id, party_type
      FROM transaction_master
      WHERE id = ? AND company_id = ?
      LIMIT 1
      `,
      [saleTxn.id, companyId]
    );

    const saleTxnRow = saleTxnRows[0];
    if (!saleTxnRow?.party_id) {
      await connection.rollback();
      return res.status(400).json({
        success: false,
        message: "Customer transaction party not found"
      });
    }

    const party = await getPartyByIdForCompany(connection, companyId, saleTxnRow.party_id);
    if (!party) {
      await connection.rollback();
      return res.status(404).json({
        success: false,
        message: "Customer party record not found"
      });
    }

    const [paymentCountRows] = await connection.query(
      `
      SELECT COUNT(*) AS total
      FROM invoice_transaction_link itl
      INNER JOIN transaction_master tm ON tm.id = itl.transaction_id
      WHERE itl.company_id = ?
        AND itl.invoice_no = ?
        AND tm.transaction_type = 'PAYMENT_RECEIVED'
      `,
      [companyId, invoiceNumber]
    );
    const paymentCount = Number(paymentCountRows[0]?.total || 0);
    const paymentVoucherNo = `PAY-${invoiceNumber}-${paymentCount + 1}`;

    const newDue = Math.max(currentDue - paymentAmount, 0);
    const newPaid = currentPaid + paymentAmount;
    const newStatus = newDue <= 0.009 ? "PAID" : "PARTIAL";

    const [paymentTxnInsert] = await connection.query(
      `
      INSERT INTO transaction_master
      (
        company_id, voucher_no, voucher_date, transaction_type, party_id, party_type,
        status, reference_no, invoice_no, source_module, payment_mode, payment_status,
        remarks, note, created_by
      )
      VALUES (?, ?, ?, 'PAYMENT_RECEIVED', ?, ?, 'POSTED', ?, ?, 'sales-history', ?, ?, ?, ?, ?)
      `,
      [
        companyId,
        paymentVoucherNo,
        paymentDate,
        party.id,
        saleTxnRow.party_type || party.party_type || "CUSTOMER",
        invoiceNumber,
        invoiceNumber,
        paymentMode || "Cash",
        newStatus,
        "Due payment received from sales history",
        note || `Additional receipt ${paymentAmount.toFixed(2)}`,
        createdBy
      ]
    );

    const paymentTransactionId = paymentTxnInsert.insertId;

    await connection.query(
      `
      INSERT INTO transaction_settlements
      (
        company_id, transaction_id, settlement_type, against_transaction_id,
        against_invoice_no, against_voucher_no, cash_amount, settlement_date,
        remarks, created_by
      )
      VALUES (?, ?, 'CASH', ?, ?, ?, ?, ?, ?, ?)
      `,
      [
        companyId,
        paymentTransactionId,
        saleTxn.id,
        invoiceNumber,
        saleTxn.voucher_no || invoiceNumber,
        paymentAmount,
        paymentDate,
        note || "Sales history due settlement",
        createdBy
      ]
    );

    await connection.query(
      `
      INSERT INTO invoice_transaction_link
      (company_id, invoice_no, transaction_id, link_type, remarks, created_by)
      VALUES (?, ?, ?, 'PAYMENT_RECEIVED', ?, ?)
      `,
      [companyId, invoiceNumber, paymentTransactionId, "Sales history payment posting", createdBy]
    );

    await createCashLedgerEntry(connection, {
      companyId,
      partyId: party.id,
      transactionId: paymentTransactionId,
      entryDate: paymentDate,
      entryType: "CREDIT",
      debitAmount: 0,
      creditAmount: paymentAmount,
      referenceType: "PAYMENT_RECEIVED",
      referenceNo: paymentVoucherNo,
      remarks: note || "Sales history payment received",
      paymentMode,
      accountId: req.body.accountId ?? req.body.account_id ?? req.body.paymentAccountId ?? null,
      branchId: req.body.branchId ?? req.body.branch_id ?? saleRow.branch_id ?? null,
      createdBy
    });

    await connection.query(
      `
      UPDATE sales_history
      SET paid_amount = ?, due_amount = ?, payment_status = ?, payment_mode = ?
      WHERE id = ?
      `,
      [newPaid, newDue, newStatus, paymentMode || saleRow.payment_mode || "Cash", saleRow.id]
    );

    await writeAuditLogSafe(connection, req, {
      companyId,
      userId: createdBy ?? null,
      actionType: "PAYMENT_UPDATE",
      entityType: "PAYMENT",
      entityId: invoiceNumber,
      beforeData: {
        id: saleRow.id,
        invoice_number: saleRow.invoice_number,
        payment_mode: saleRow.payment_mode,
        payment_status: saleRow.payment_status,
        paid_amount: toNumber(saleRow.paid_amount),
        due_amount: toNumber(saleRow.due_amount),
        total_amount: toNumber(saleRow.total_amount)
      },
      afterData: {
        id: saleRow.id,
        invoice_number: invoiceNumber,
        payment_mode: paymentMode || saleRow.payment_mode || "Cash",
        payment_status: newStatus,
        paid_amount: newPaid,
        due_amount: newDue,
        total_amount: toNumber(saleRow.total_amount),
        payment_received: paymentAmount,
        transaction_id: paymentTransactionId,
        note
      }
    });

    await recalcPartyBalanceSummary(connection, companyId, party.id, paymentTransactionId);
    await connection.commit();

    return res.json({
      success: true,
      message: "Payment updated successfully",
      paidAmount: newPaid,
      dueAmount: newDue,
      paymentStatus: newStatus,
      transactionId: paymentTransactionId,
      settlementCreated: true
    });
  } catch (error) {
    if (connection) {
      try {
        await connection.rollback();
      } catch (_) {}
    }
    console.error("Sales history payment update error:", error);
    return res.status(500).json({
      success: false,
      message: "Payment update failed"
    });
  } finally {
    if (connection) connection.release();
  }
});

function buildSaleCancellationSnapshot({
  sale = null,
  saleItems = [],
  stockRows = [],
  linkedTransactions = [],
  cashLedgerRows = [],
  metalLedgerRows = [],
  returnRows = []
} = {}) {
  return {
    sale,
    saleItems,
    stockRows,
    linkedTransactions,
    cashLedgerRows,
    metalLedgerRows,
    returnRows,
    capturedAt: new Date().toISOString()
  };
}

function buildStockRestorePlan(companyId, invoiceNumber, saleItems = [], stockRows = [], userContext = {}) {
  const blockingReasons = [];
  const warnings = [];
  const stockByBarcode = new Map();

  stockRows.forEach((row) => {
    const key = String(row.barcode || "").trim();
    if (!key) return;
    if (!stockByBarcode.has(key)) stockByBarcode.set(key, []);
    stockByBarcode.get(key).push(row);
  });

  const stockImpact = saleItems.map((item) => {
    const barcode = String(item.barcode || "").trim();
    const rows = barcode ? stockByBarcode.get(barcode) || [] : [];
    const stock = rows[0] || null;
    const stockStatus = String(stock?.status || "").trim().toUpperCase();
    const effectiveStockState = stock ? getEffectiveStockState(stock) : "";
    const itemReasons = [];
    const itemWarnings = [];

    if (!barcode) {
      itemWarnings.push("Sale item has no barcode");
    }

    if (rows.length > 1) {
      itemReasons.push("Duplicate stock rows found for barcode");
    }

    if (barcode && !stock) {
      itemReasons.push("Stock row not found for barcode");
    }

    if (stock && Number(stock.company_id || 0) !== Number(companyId || 0)) {
      itemReasons.push("Stock row belongs to another company");
    }

    if (stock && stockStatus !== "SOLD") {
      itemReasons.push("Stock is not currently SOLD");
    }

    if (stock && String(stock.invoice_number || "").trim() !== invoiceNumber) {
      itemReasons.push("Stock invoice number does not match this invoice");
    }

    if (stock && ["IN_TRANSIT", "TRANSFER_SHORTAGE"].includes(effectiveStockState)) {
      itemReasons.push("Stock is already transferred or in branch-transfer exception state");
    }

    if (stock && ["RETURN_TO_STOCK", "DAMAGED_RETURN", "DAMAGED", "DELETED"].includes(stockStatus)) {
      itemReasons.push("Stock is already returned, damaged, or deleted");
    }

    if (stock && userContext.isBranchLocked && Number(stock.current_branch_id || 0) !== Number(userContext.userBranchId || 0)) {
      itemReasons.push("Stock branch does not match the user's assigned branch");
    }

    if (itemReasons.length) {
      blockingReasons.push(...itemReasons.map((reason) => `${barcode || "Unbarcoded item"}: ${reason}`));
    }

    if (itemWarnings.length) {
      warnings.push(...itemWarnings.map((warning) => `${barcode || "Unbarcoded item"}: ${warning}`));
    }

    return {
      saleItemId: item.id,
      barcode,
      productName: item.product_name || "",
      lotNumber: item.lot_number || "",
      saleItemStatus: item.item_status || "",
      currentStockStatus: stock?.status || "",
      currentStockState: effectiveStockState,
      currentBranchId: stock?.current_branch_id ?? null,
      stockInvoiceNumber: stock?.invoice_number || "",
      restorePreview: stock
        ? {
            fromStatus: stock.status || "",
            toStatus: "IN_STOCK",
            clearInvoiceNumber: true,
            clearSoldAt: true
          }
        : null,
      blockingReasons: itemReasons,
      warnings: itemWarnings
    };
  });

  return {
    stockImpact,
    blockingReasons,
    warnings
  };
}

function buildLedgerReversalPlan(linkedTransactions = [], cashLedgerRows = [], metalLedgerRows = []) {
  const paymentTransactions = linkedTransactions.filter((row) => {
    const type = String(row.transaction_type || "").trim().toUpperCase();
    return type === "PAYMENT_RECEIVED" || type === "METAL_SETTLEMENT_RECEIVED";
  });
  const blockingReasons = [];

  if (paymentTransactions.length) {
    blockingReasons.push("Settlement/payment transaction exists and needs a controlled reversal flow");
  }

  const cashDebit = cashLedgerRows.reduce((sum, row) => sum + toNumber(row.debit_amount), 0);
  const cashCredit = cashLedgerRows.reduce((sum, row) => sum + toNumber(row.credit_amount), 0);
  const metalSummary = metalLedgerRows.reduce((acc, row) => {
    const metalType = normalizeMetalType(row.metal_type) || "UNKNOWN";
    if (!acc[metalType]) {
      acc[metalType] = {
        grossIn: 0,
        grossOut: 0,
        fineIn: 0,
        fineOut: 0
      };
    }
    acc[metalType].grossIn += toNumber(row.gross_in);
    acc[metalType].grossOut += toNumber(row.gross_out);
    acc[metalType].fineIn += toNumber(row.fine_in);
    acc[metalType].fineOut += toNumber(row.fine_out);
    return acc;
  }, {});

  return {
    blockingReasons,
    ledgerImpact: {
      linkedTransactions: linkedTransactions.map((row) => ({
        id: row.id,
        voucherNo: row.voucher_no || "",
        transactionType: row.transaction_type || "",
        status: row.status || "",
        linkType: row.link_type || "",
        paymentMode: row.payment_mode || "",
        paymentStatus: row.payment_status || "",
        voucherDate: row.voucher_date || ""
      })),
      cash: {
        rows: cashLedgerRows,
        totalDebit: cashDebit,
        totalCredit: cashCredit,
        netReceivableImpact: cashDebit - cashCredit,
        reversalPreview: {
          debitToCredit: cashDebit,
          creditToDebit: cashCredit
        }
      },
      metal: {
        rows: metalLedgerRows,
        summary: metalSummary,
        reversalPreview: Object.entries(metalSummary).map(([metalType, summary]) => ({
          metalType,
          grossInToOut: summary.grossIn,
          grossOutToIn: summary.grossOut,
          fineInToOut: summary.fineIn,
          fineOutToIn: summary.fineOut
        }))
      }
    }
  };
}

async function buildSaleCancellationPreview(companyId, invoiceNumber, userContext = {}) {
  const cleanCompanyId = Number(companyId || 0);
  const cleanInvoiceNumber = String(invoiceNumber || "").trim();
  const existingConnection = userContext.connection;
  const connection = existingConnection || await pool.getConnection();

  try {
    const [saleRows] = await connection.query(
      `
      SELECT *
      FROM sales_history
      WHERE invoice_number = ? AND company_id = ?
      ORDER BY id DESC
      LIMIT 1
      `,
      [cleanInvoiceNumber, cleanCompanyId]
    );

    if (!saleRows.length) {
      return {
        ok: false,
        status: 404,
        body: {
          success: false,
          message: "Sale record not found"
        }
      };
    }

    const sale = saleRows[0];
    const [saleItems] = await connection.query(
      `
      SELECT *
      FROM sales_items
      WHERE invoice_number = ? AND company_id = ?
      ORDER BY id ASC
      `,
      [cleanInvoiceNumber, cleanCompanyId]
    );

    const barcodes = [
      ...new Set(
        saleItems
          .map((item) => String(item.barcode || "").trim())
          .filter(Boolean)
      )
    ];

    let stockRows = [];
    if (barcodes.length) {
      const placeholders = barcodes.map(() => "?").join(", ");
      const [rows] = await connection.query(
        `
        SELECT *
        FROM stock
        WHERE company_id = ?
          AND barcode IN (${placeholders})
        ORDER BY id ASC
        `,
        [cleanCompanyId, ...barcodes]
      );
      stockRows = rows;
    }

    const [linkedTransactions] = await connection.query(
      `
      SELECT
        itl.id AS link_id,
        itl.link_type,
        itl.remarks AS link_remarks,
        tm.*
      FROM invoice_transaction_link itl
      INNER JOIN transaction_master tm
        ON tm.id = itl.transaction_id
       AND tm.company_id = itl.company_id
      WHERE itl.company_id = ?
        AND itl.invoice_no = ?
      ORDER BY tm.id ASC
      `,
      [cleanCompanyId, cleanInvoiceNumber]
    );

    const linkedTransactionIds = linkedTransactions.map((row) => Number(row.id || 0)).filter(Boolean);
    let cashLedgerRows = [];
    let metalLedgerRows = [];

    if (linkedTransactionIds.length) {
      const placeholders = linkedTransactionIds.map(() => "?").join(", ");
      const [cashRows] = await connection.query(
        `
        SELECT *
        FROM cash_ledger
        WHERE company_id = ?
          AND transaction_id IN (${placeholders})
        ORDER BY id ASC
        `,
        [cleanCompanyId, ...linkedTransactionIds]
      );
      cashLedgerRows = cashRows;

      const [metalRows] = await connection.query(
        `
        SELECT *
        FROM metal_ledger
        WHERE company_id = ?
          AND transaction_id IN (${placeholders})
        ORDER BY id ASC
        `,
        [cleanCompanyId, ...linkedTransactionIds]
      );
      metalLedgerRows = metalRows;
    }

    let returnRows = [];
    if (barcodes.length) {
      const placeholders = barcodes.map(() => "?").join(", ");
      const [rows] = await connection.query(
        `
        SELECT *
        FROM return_history
        WHERE company_id = ?
          AND (
            invoice_number = ?
            OR barcode IN (${placeholders})
          )
        ORDER BY id ASC
        `,
        [cleanCompanyId, cleanInvoiceNumber, ...barcodes]
      );
      returnRows = rows;
    } else {
      const [rows] = await connection.query(
        `
        SELECT *
        FROM return_history
        WHERE company_id = ?
          AND invoice_number = ?
        ORDER BY id ASC
        `,
        [cleanCompanyId, cleanInvoiceNumber]
      );
      returnRows = rows;
    }

    const blockingReasons = [];
    const warnings = [];
    const saleStatus = String(sale.status || "").trim().toUpperCase();

    if (Number(sale.is_deleted || 0) === 1) {
      blockingReasons.push("Invoice is already deleted");
    }

    if (saleStatus === "CANCELLED") {
      blockingReasons.push("Invoice is already cancelled");
    }

    if (!saleItems.length) {
      blockingReasons.push("Invoice has no sale items to inspect");
    }

    if (returnRows.length) {
      blockingReasons.push("Return already exists for this invoice or one of its barcodes");
    }

    const stockPlan = buildStockRestorePlan(cleanCompanyId, cleanInvoiceNumber, saleItems, stockRows, userContext);
    blockingReasons.push(...stockPlan.blockingReasons);
    warnings.push(...stockPlan.warnings);

    const ledgerPlan = buildLedgerReversalPlan(linkedTransactions, cashLedgerRows, metalLedgerRows);
    blockingReasons.push(...ledgerPlan.blockingReasons);
    const saleTransactions = linkedTransactions.filter((row) => String(row.transaction_type || "").trim().toUpperCase() === "SALE_INVOICE");
    const nonSaleTransactions = linkedTransactions.filter((row) => String(row.transaction_type || "").trim().toUpperCase() !== "SALE_INVOICE");
    const cashCredit = cashLedgerRows.reduce((sum, row) => sum + toNumber(row.credit_amount), 0);
    if (!saleTransactions.length) {
      blockingReasons.push("Original SALE_INVOICE transaction was not found");
    }
    if (saleTransactions.length > 1) {
      blockingReasons.push("Multiple SALE_INVOICE transactions found");
    }
    if (nonSaleTransactions.length) {
      blockingReasons.push("Only unpaid/simple invoices can be cancelled in this phase");
    }
    if (metalLedgerRows.length) {
      blockingReasons.push("Metal ledger impact exists and is not supported in this phase");
    }
    if (cashCredit > 0) {
      blockingReasons.push("Cash credit/payment ledger impact exists and is not supported in this phase");
    }

    const beforeSnapshot = buildSaleCancellationSnapshot({
      sale,
      saleItems,
      stockRows,
      linkedTransactions,
      cashLedgerRows,
      metalLedgerRows,
      returnRows
    });

    return {
      ok: true,
      status: 200,
      body: {
        success: true,
        canCancel: blockingReasons.length === 0,
        invoiceNumber: cleanInvoiceNumber,
        saleSummary: {
          id: sale.id,
          invoiceNumber: sale.invoice_number,
          customerName: sale.customer_name || "",
          invoiceDate: sale.invoice_date || "",
          status: sale.status || "",
          isDeleted: Number(sale.is_deleted || 0) === 1,
          paymentStatus: sale.payment_status || "",
          paymentMode: sale.payment_mode || "",
          paidAmount: toNumber(sale.paid_amount),
          dueAmount: toNumber(sale.due_amount),
          totalAmount: toNumber(sale.total_amount),
          totalItems: saleItems.length,
          totalWeight: toNumber(sale.total_weight)
        },
        stockImpact: stockPlan.stockImpact,
        ledgerImpact: ledgerPlan.ledgerImpact,
        returnImpact: {
          rows: returnRows,
          count: returnRows.length
        },
        cancellationSnapshot: beforeSnapshot,
        blockingReasons: [...new Set(blockingReasons)],
        warnings: [...new Set(warnings)]
      }
    };
  } finally {
    if (!existingConnection) connection.release();
  }
}

async function cancelSimpleUnpaidSaleInvoice({
  connection,
  req,
  access,
  companyId,
  invoiceNumber,
  reason
}) {
  const cleanCompanyId = Number(companyId || 0);
  const cleanInvoiceNumber = String(invoiceNumber || "").trim();
  const cleanReason = String(reason || "").trim();
  const cancelledBy = access.actingUserId ?? getRequestedUserId(req) ?? null;

  const preview = await buildSaleCancellationPreview(cleanCompanyId, cleanInvoiceNumber, {
    ...access,
    connection
  });

  if (!preview.ok || !preview.body?.success) {
    return {
      ok: false,
      status: preview.status || 400,
      body: preview.body || {
        success: false,
        message: "Cancel preview failed"
      }
    };
  }

  if (!preview.body.canCancel) {
    return {
      ok: false,
      status: 409,
      body: {
        success: false,
        message: "Invoice cannot be cancelled safely",
        blockingReasons: preview.body.blockingReasons || [],
        warnings: preview.body.warnings || [],
        preview: preview.body
      }
    };
  }

  const snapshot = preview.body.cancellationSnapshot || {};
  const sale = snapshot.sale || null;
  const saleItems = Array.isArray(snapshot.saleItems) ? snapshot.saleItems : [];
  const stockRows = Array.isArray(snapshot.stockRows) ? snapshot.stockRows : [];
  const linkedTransactions = Array.isArray(snapshot.linkedTransactions) ? snapshot.linkedTransactions : [];
  const cashLedgerRows = Array.isArray(snapshot.cashLedgerRows) ? snapshot.cashLedgerRows : [];
  const metalLedgerRows = Array.isArray(snapshot.metalLedgerRows) ? snapshot.metalLedgerRows : [];
  const returnRows = Array.isArray(snapshot.returnRows) ? snapshot.returnRows : [];

  const saleTransactions = linkedTransactions.filter((row) => String(row.transaction_type || "").trim().toUpperCase() === "SALE_INVOICE");
  const nonSaleTransactions = linkedTransactions.filter((row) => String(row.transaction_type || "").trim().toUpperCase() !== "SALE_INVOICE");
  const cashDebit = cashLedgerRows.reduce((sum, row) => sum + toNumber(row.debit_amount), 0);
  const cashCredit = cashLedgerRows.reduce((sum, row) => sum + toNumber(row.credit_amount), 0);
  const blocked = [];

  if (!sale?.id) blocked.push("Sale row is missing");
  if (Number(sale?.is_deleted || 0) === 1) blocked.push("Invoice is already deleted");
  if (String(sale?.status || "").trim().toUpperCase() === "CANCELLED") blocked.push("Invoice is already cancelled");
  if (returnRows.length) blocked.push("Return already exists for this invoice");
  if (!saleTransactions.length) blocked.push("Original SALE_INVOICE transaction was not found");
  if (saleTransactions.length > 1) blocked.push("Multiple SALE_INVOICE transactions found");
  if (nonSaleTransactions.length) blocked.push("Only unpaid/simple invoices can be cancelled in this phase");
  if (metalLedgerRows.length) blocked.push("Metal ledger impact exists and is not supported in this phase");
  if (cashCredit > 0) blocked.push("Cash credit/payment ledger impact exists and is not supported in this phase");
  if (!stockRows.length && saleItems.some((item) => String(item.barcode || "").trim())) blocked.push("Stock rows are missing");

  if (blocked.length) {
    return {
      ok: false,
      status: 409,
      body: {
        success: false,
        message: "Invoice cannot be cancelled in simple unpaid mode",
        blockingReasons: [...new Set(blocked)],
        preview: preview.body
      }
    };
  }

  const [insertCancellation] = await connection.query(
    `
    INSERT INTO sales_cancellations
    (
      company_id, invoice_number, sale_id, status, reason, blocked_reason,
      before_snapshot, cancelled_by, cancelled_at, created_at, updated_at
    )
    VALUES (?, ?, ?, 'PENDING', ?, NULL, ?, ?, NOW(), NOW(), NOW())
    `,
    [
      cleanCompanyId,
      cleanInvoiceNumber,
      sale.id,
      cleanReason,
      safeJsonStringify(snapshot),
      cancelledBy
    ]
  );
  const cancellationId = Number(insertCancellation.insertId || 0);

  const barcodes = [
    ...new Set(
      saleItems
        .map((item) => String(item.barcode || "").trim())
        .filter(Boolean)
    )
  ];

  for (const barcode of barcodes) {
    const [restoreStockRows] = await connection.query(
      `
      SELECT *
      FROM stock
      WHERE company_id = ?
        AND barcode = ?
        AND invoice_number = ?
      LIMIT 1
      FOR UPDATE
      `,
      [cleanCompanyId, barcode, cleanInvoiceNumber]
    );

    if (!restoreStockRows.length) {
      throw new Error(`Stock restore preview row not found for barcode ${barcode}`);
    }

    await assertActiveBarcodeAvailable(cleanCompanyId, {
      ...restoreStockRows[0],
      status: "IN_STOCK",
      stock_state: "IN_STOCK",
      invoice_number: "",
      deleted_at: null
    }, {
      db: connection,
      excludeStockId: restoreStockRows[0].id,
      req,
      access,
      context: "SALE_CANCELLATION_RESTORE"
    });

    const [stockUpdate] = await connection.query(
      `
      UPDATE stock
      SET status = 'IN_STOCK',
          stock_state = 'IN_STOCK',
          invoice_number = '',
          sold_at = NULL,
          updated_at = NOW()
      WHERE company_id = ?
        AND barcode = ?
        AND UPPER(COALESCE(status, '')) = 'SOLD'
        AND UPPER(COALESCE(NULLIF(TRIM(stock_state), ''), status, 'IN_STOCK')) NOT IN ('IN_TRANSIT', 'TRANSFER_SHORTAGE', 'DAMAGED_RETURN', 'DAMAGED', 'DELETED')
        AND invoice_number = ?
      `,
      [cleanCompanyId, barcode, cleanInvoiceNumber]
    );

    const affectedRows = assertSingleStockRowAffected(stockUpdate);
    if (affectedRows !== 1) {
      throw new Error(`Stock restore failed for barcode ${barcode}`);
    }

    await appendBarcodeLifecycleEvent(connection, {
      companyId: cleanCompanyId,
      barcode,
      stockId: restoreStockRows[0].id,
      lotNo: restoreStockRows[0].lot_number,
      serial: restoreStockRows[0].serial,
      branchId: restoreStockRows[0].current_branch_id,
      invoiceNumber: cleanInvoiceNumber,
      transactionId: null,
      eventType: BARCODE_LIFECYCLE_EVENT_TYPES.SALE_CANCELLED_STOCK_RESTORED,
      eventTitle: "Sale Cancelled Stock Restored",
      eventDescription: "Stock restored during unpaid sale cancellation",
      eventPayload: {
        cancellationId,
        reason: cleanReason,
        previousStatus: restoreStockRows[0].status,
        previousStockState: restoreStockRows[0].stock_state
      },
      sourceTable: "sales_cancellations",
      sourceId: cancellationId,
      createdBy: cancelledBy
    });
  }

  const saleTxn = saleTransactions[0];
  const reversalVoucherNo = `REV-${cleanInvoiceNumber}-${cancellationId}`;
  const [reversalInsert] = await connection.query(
    `
    INSERT INTO transaction_master
    (
      company_id, voucher_no, voucher_date, transaction_type, party_id, party_type,
      status, reference_no, invoice_no, source_module, payment_mode, payment_status,
      remarks, note, reversal_of_transaction_id, created_by
    )
    VALUES (?, ?, CURDATE(), 'SALE_INVOICE_REVERSAL', ?, ?, 'POSTED', ?, ?, 'sales-cancellation', ?, ?, ?, ?, ?, ?)
    `,
    [
      cleanCompanyId,
      reversalVoucherNo,
      saleTxn.party_id,
      saleTxn.party_type || "CUSTOMER",
      cleanInvoiceNumber,
      cleanInvoiceNumber,
      saleTxn.payment_mode || "",
      "CANCELLED",
      "Auto reversal for cancelled unpaid invoice",
      cleanReason,
      saleTxn.id,
      cancelledBy
    ]
  );
  const reversalTransactionId = Number(reversalInsert.insertId || 0);

  await connection.query(
    `
    INSERT INTO invoice_transaction_link
    (company_id, invoice_no, transaction_id, link_type, remarks, created_by)
    VALUES (?, ?, ?, 'SALE_INVOICE_REVERSAL', ?, ?)
    `,
    [cleanCompanyId, cleanInvoiceNumber, reversalTransactionId, "Sale cancellation reversal", cancelledBy]
  );

  if (cashDebit > 0) {
    await createCashLedgerEntry(connection, {
      companyId: cleanCompanyId,
      partyId: saleTxn.party_id,
      transactionId: reversalTransactionId,
      entryDate: getTodayDateOnly(),
      entryType: "CREDIT",
      debitAmount: 0,
      creditAmount: cashDebit,
      referenceType: "SALE_INVOICE_REVERSAL",
      referenceNo: reversalVoucherNo,
      remarks: `Cancelled invoice ${cleanInvoiceNumber}`,
      createdBy: cancelledBy
    });
  }

  await connection.query(
    `
    UPDATE sales_history
    SET status = 'CANCELLED',
        is_deleted = 1,
        deleted_at = COALESCE(deleted_at, NOW()),
        deleted_by = COALESCE(deleted_by, ?),
        delete_reason = ?,
        cancelled_at = NOW(),
        cancelled_by = ?,
        cancellation_reason = ?,
        cancellation_id = ?
    WHERE id = ?
      AND company_id = ?
    `,
    [cancelledBy, cleanReason, cancelledBy, cleanReason, cancellationId, sale.id, cleanCompanyId]
  );

  await connection.query(
    `
    UPDATE sales_items
    SET item_status = 'CANCELLED',
        is_deleted = 1,
        deleted_at = COALESCE(deleted_at, NOW()),
        deleted_by = COALESCE(deleted_by, ?),
        delete_reason = ?,
        cancelled_at = NOW(),
        cancelled_by = ?
    WHERE invoice_number = ?
      AND company_id = ?
    `,
    [cancelledBy, cleanReason, cancelledBy, cleanInvoiceNumber, cleanCompanyId]
  );

  await recalcPartyBalanceSummary(connection, cleanCompanyId, saleTxn.party_id, reversalTransactionId);

  const afterSnapshot = buildSaleCancellationSnapshot({
    sale: {
      ...sale,
      status: "CANCELLED",
      is_deleted: 1,
      cancellation_id: cancellationId,
      cancellation_reason: cleanReason,
      cancelled_by: cancelledBy
    },
    saleItems: saleItems.map((item) => ({
      ...item,
      item_status: "CANCELLED",
      is_deleted: 1,
      cancelled_by: cancelledBy
    })),
    stockRows: stockRows.map((stock) => ({
      ...stock,
      status: "IN_STOCK",
      stock_state: "IN_STOCK",
      invoice_number: "",
      sold_at: null
    })),
    linkedTransactions: [
      ...linkedTransactions,
      {
        id: reversalTransactionId,
        voucher_no: reversalVoucherNo,
        transaction_type: "SALE_INVOICE_REVERSAL",
        reversal_of_transaction_id: saleTxn.id
      }
    ],
    cashLedgerRows,
    metalLedgerRows,
    returnRows
  });

  await connection.query(
    `
    UPDATE sales_cancellations
    SET status = 'APPLIED',
        after_snapshot = ?,
        updated_at = NOW()
    WHERE id = ?
      AND company_id = ?
    `,
    [safeJsonStringify(afterSnapshot), cancellationId, cleanCompanyId]
  );

  await writeAuditLogSafe(connection, req, {
    companyId: cleanCompanyId,
    userId: cancelledBy,
    actionType: "CANCEL",
    entityType: "SALE",
    entityId: cleanInvoiceNumber,
    moduleName: "sales-history",
    status: "success",
    message: "Sale invoice cancelled",
    beforeData: snapshot,
    afterData: afterSnapshot,
    metadata: {
      cancellationId,
      reversalTransactionId,
      reason: cleanReason
    }
  });

  return {
    ok: true,
    status: 200,
    body: {
      success: true,
      message: "Invoice cancelled successfully",
      invoiceNumber: cleanInvoiceNumber,
      cancellationId,
      reversalTransactionId,
      restoredStockCount: barcodes.length
    }
  };
}

app.get("/sales-history/:invoiceNumber/cancel-preview", authMiddleware, checkRole(["SUPERADMIN", "OWNER", "ACCOUNTS"]), async (req, res) => {
  let connection;

  try {
    const invoiceNumber = String(req.params.invoiceNumber || "").trim();
    const access = await resolveBranchAccessContext(req, {
      requireCompanyScope: true
    });

    if (!access.ok) {
      return sendAccessError(res, access);
    }

    if (!invoiceNumber) {
      return res.status(400).json({
        success: false,
        message: "Invoice number is required"
      });
    }

    const preview = await buildSaleCancellationPreview(access.companyScope, invoiceNumber, access);
    return res.status(preview.status || 200).json(preview.body);

    const companyId = access.companyScope;
    connection = await pool.getConnection();

    const [saleRows] = await connection.query(
      `
      SELECT *
      FROM sales_history
      WHERE invoice_number = ? AND company_id = ?
      ORDER BY id DESC
      LIMIT 1
      `,
      [invoiceNumber, companyId]
    );

    if (!saleRows.length) {
      return res.status(404).json({
        success: false,
        message: "Sale record not found"
      });
    }

    const sale = saleRows[0];
    const [itemRows] = await connection.query(
      `
      SELECT *
      FROM sales_items
      WHERE invoice_number = ? AND company_id = ?
      ORDER BY id ASC
      `,
      [invoiceNumber, companyId]
    );

    const barcodes = [
      ...new Set(
        itemRows
          .map((item) => String(item.barcode || "").trim())
          .filter(Boolean)
      )
    ];

    let stockRows = [];
    if (barcodes.length) {
      const placeholders = barcodes.map(() => "?").join(", ");
      const [rows] = await connection.query(
        `
        SELECT *
        FROM stock
        WHERE company_id = ?
          AND barcode IN (${placeholders})
        ORDER BY id ASC
        `,
        [companyId, ...barcodes]
      );
      stockRows = rows;
    }

    const [linkedTransactionRows] = await connection.query(
      `
      SELECT
        itl.id AS link_id,
        itl.link_type,
        itl.remarks AS link_remarks,
        tm.*
      FROM invoice_transaction_link itl
      INNER JOIN transaction_master tm
        ON tm.id = itl.transaction_id
       AND tm.company_id = itl.company_id
      WHERE itl.company_id = ?
        AND itl.invoice_no = ?
      ORDER BY tm.id ASC
      `,
      [companyId, invoiceNumber]
    );

    const linkedTransactionIds = linkedTransactionRows.map((row) => Number(row.id || 0)).filter(Boolean);
    let cashLedgerRows = [];
    let metalLedgerRows = [];

    if (linkedTransactionIds.length) {
      const placeholders = linkedTransactionIds.map(() => "?").join(", ");
      const [cashRows] = await connection.query(
        `
        SELECT *
        FROM cash_ledger
        WHERE company_id = ?
          AND transaction_id IN (${placeholders})
        ORDER BY id ASC
        `,
        [companyId, ...linkedTransactionIds]
      );
      cashLedgerRows = cashRows;

      const [metalRows] = await connection.query(
        `
        SELECT *
        FROM metal_ledger
        WHERE company_id = ?
          AND transaction_id IN (${placeholders})
        ORDER BY id ASC
        `,
        [companyId, ...linkedTransactionIds]
      );
      metalLedgerRows = metalRows;
    }

    let returnRows = [];
    if (barcodes.length) {
      const placeholders = barcodes.map(() => "?").join(", ");
      const [rows] = await connection.query(
        `
        SELECT *
        FROM return_history
        WHERE company_id = ?
          AND (
            invoice_number = ?
            OR barcode IN (${placeholders})
          )
        ORDER BY id ASC
        `,
        [companyId, invoiceNumber, ...barcodes]
      );
      returnRows = rows;
    } else {
      const [rows] = await connection.query(
        `
        SELECT *
        FROM return_history
        WHERE company_id = ?
          AND invoice_number = ?
        ORDER BY id ASC
        `,
        [companyId, invoiceNumber]
      );
      returnRows = rows;
    }

    const blockingReasons = [];
    const warnings = [];
    const saleStatus = String(sale.status || "").trim().toUpperCase();

    if (Number(sale.is_deleted || 0) === 1) {
      blockingReasons.push("Invoice is already deleted");
    }

    if (saleStatus === "CANCELLED") {
      blockingReasons.push("Invoice is already cancelled");
    }

    if (!itemRows.length) {
      blockingReasons.push("Invoice has no sale items to inspect");
    }

    if (returnRows.length) {
      blockingReasons.push("Return already exists for this invoice or one of its barcodes");
    }

    const paymentTransactions = linkedTransactionRows.filter((row) => {
      const type = String(row.transaction_type || "").trim().toUpperCase();
      return type === "PAYMENT_RECEIVED" || type === "METAL_SETTLEMENT_RECEIVED";
    });

    if (paymentTransactions.length) {
      blockingReasons.push("Settlement/payment transaction exists and needs a controlled reversal flow");
    }

    const stockByBarcode = new Map();
    stockRows.forEach((row) => {
      const key = String(row.barcode || "").trim();
      if (!key) return;
      if (!stockByBarcode.has(key)) stockByBarcode.set(key, []);
      stockByBarcode.get(key).push(row);
    });

    const stockImpact = itemRows.map((item) => {
      const barcode = String(item.barcode || "").trim();
      const rows = barcode ? stockByBarcode.get(barcode) || [] : [];
      const stock = rows[0] || null;
      const stockStatus = String(stock?.status || "").trim().toUpperCase();
      const effectiveStockState = stock ? getEffectiveStockState(stock) : "";
      const itemReasons = [];
      const itemWarnings = [];

      if (!barcode) {
        itemWarnings.push("Sale item has no barcode");
      }

      if (rows.length > 1) {
        itemReasons.push("Duplicate stock rows found for barcode");
      }

      if (barcode && !stock) {
        itemReasons.push("Stock row not found for barcode");
      }

      if (stock && Number(stock.company_id || 0) !== Number(companyId || 0)) {
        itemReasons.push("Stock row belongs to another company");
      }

      if (stock && stockStatus !== "SOLD") {
        itemReasons.push("Stock is not currently SOLD");
      }

      if (stock && String(stock.invoice_number || "").trim() !== invoiceNumber) {
        itemReasons.push("Stock invoice number does not match this invoice");
      }

      if (stock && ["IN_TRANSIT", "TRANSFER_SHORTAGE"].includes(effectiveStockState)) {
        itemReasons.push("Stock is already transferred or in branch-transfer exception state");
      }

      if (stock && ["RETURN_TO_STOCK", "DAMAGED_RETURN", "DAMAGED", "DELETED"].includes(stockStatus)) {
        itemReasons.push("Stock is already returned, damaged, or deleted");
      }

      if (stock && access.isBranchLocked && Number(stock.current_branch_id || 0) !== Number(access.userBranchId || 0)) {
        itemReasons.push("Stock branch does not match the user's assigned branch");
      }

      if (itemReasons.length) {
        blockingReasons.push(...itemReasons.map((reason) => `${barcode || "Unbarcoded item"}: ${reason}`));
      }

      if (itemWarnings.length) {
        warnings.push(...itemWarnings.map((warning) => `${barcode || "Unbarcoded item"}: ${warning}`));
      }

      return {
        saleItemId: item.id,
        barcode,
        productName: item.product_name || "",
        lotNumber: item.lot_number || "",
        saleItemStatus: item.item_status || "",
        currentStockStatus: stock?.status || "",
        currentStockState: effectiveStockState,
        currentBranchId: stock?.current_branch_id ?? null,
        stockInvoiceNumber: stock?.invoice_number || "",
        restorePreview: stock
          ? {
              fromStatus: stock.status || "",
              toStatus: "IN_STOCK",
              clearInvoiceNumber: true,
              clearSoldAt: true
            }
          : null,
        blockingReasons: itemReasons,
        warnings: itemWarnings
      };
    });

    const cashDebit = cashLedgerRows.reduce((sum, row) => sum + toNumber(row.debit_amount), 0);
    const cashCredit = cashLedgerRows.reduce((sum, row) => sum + toNumber(row.credit_amount), 0);
    const metalSummary = metalLedgerRows.reduce((acc, row) => {
      const metalType = normalizeMetalType(row.metal_type) || "UNKNOWN";
      if (!acc[metalType]) {
        acc[metalType] = {
          grossIn: 0,
          grossOut: 0,
          fineIn: 0,
          fineOut: 0
        };
      }
      acc[metalType].grossIn += toNumber(row.gross_in);
      acc[metalType].grossOut += toNumber(row.gross_out);
      acc[metalType].fineIn += toNumber(row.fine_in);
      acc[metalType].fineOut += toNumber(row.fine_out);
      return acc;
    }, {});

    return res.json({
      success: true,
      canCancel: blockingReasons.length === 0,
      invoiceNumber,
      saleSummary: {
        id: sale.id,
        invoiceNumber: sale.invoice_number,
        customerName: sale.customer_name || "",
        invoiceDate: sale.invoice_date || "",
        status: sale.status || "",
        isDeleted: Number(sale.is_deleted || 0) === 1,
        paymentStatus: sale.payment_status || "",
        paymentMode: sale.payment_mode || "",
        paidAmount: toNumber(sale.paid_amount),
        dueAmount: toNumber(sale.due_amount),
        totalAmount: toNumber(sale.total_amount),
        totalItems: itemRows.length,
        totalWeight: toNumber(sale.total_weight)
      },
      stockImpact,
      ledgerImpact: {
        linkedTransactions: linkedTransactionRows.map((row) => ({
          id: row.id,
          voucherNo: row.voucher_no || "",
          transactionType: row.transaction_type || "",
          status: row.status || "",
          linkType: row.link_type || "",
          paymentMode: row.payment_mode || "",
          paymentStatus: row.payment_status || "",
          voucherDate: row.voucher_date || ""
        })),
        cash: {
          rows: cashLedgerRows,
          totalDebit: cashDebit,
          totalCredit: cashCredit,
          netReceivableImpact: cashDebit - cashCredit,
          reversalPreview: {
            debitToCredit: cashDebit,
            creditToDebit: cashCredit
          }
        },
        metal: {
          rows: metalLedgerRows,
          summary: metalSummary,
          reversalPreview: Object.entries(metalSummary).map(([metalType, summary]) => ({
            metalType,
            grossInToOut: summary.grossIn,
            grossOutToIn: summary.grossOut,
            fineInToOut: summary.fineIn,
            fineOutToIn: summary.fineOut
          }))
        }
      },
      returnImpact: {
        rows: returnRows,
        count: returnRows.length
      },
      blockingReasons: [...new Set(blockingReasons)],
      warnings: [...new Set(warnings)]
    });
  } catch (error) {
    console.error("Cancel preview error:", error);
    return res.status(500).json({
      success: false,
      message: "Cancel preview failed",
      error: getErrorDetail(error)
    });
  } finally {
    if (connection) connection.release();
  }
});

app.post("/sales-history/:invoiceNumber/cancel", authMiddleware, checkRole(["OWNER", "ACCOUNTS"]), async (req, res) => {
  let connection;

  try {
    const invoiceNumber = String(req.params.invoiceNumber || "").trim();
    const reason = String(req.body?.reason || "").trim();
    const access = await resolveBranchAccessContext(req, {
      requireCompanyScope: true
    });

    if (!access.ok) {
      return sendAccessError(res, access);
    }

    if (!invoiceNumber) {
      return res.status(400).json({
        success: false,
        message: "Invoice number is required"
      });
    }

    if (!reason) {
      return res.status(400).json({
        success: false,
        message: "Cancellation reason is required"
      });
    }

    connection = await pool.getConnection();
    await connection.beginTransaction();

    const [saleRows] = await connection.query(
      `
      SELECT *
      FROM sales_history
      WHERE invoice_number = ?
        AND company_id = ?
      ORDER BY id DESC
      LIMIT 1
      FOR UPDATE
      `,
      [invoiceNumber, access.companyScope]
    );

    if (!saleRows.length) {
      await connection.rollback();
      return res.status(404).json({
        success: false,
        message: "Sale record not found"
      });
    }

    const [saleItemRows] = await connection.query(
      `
      SELECT *
      FROM sales_items
      WHERE invoice_number = ?
        AND company_id = ?
      ORDER BY id ASC
      FOR UPDATE
      `,
      [invoiceNumber, access.companyScope]
    );

    const barcodes = [
      ...new Set(
        saleItemRows
          .map((item) => String(item.barcode || "").trim())
          .filter(Boolean)
      )
    ];

    if (barcodes.length) {
      const placeholders = barcodes.map(() => "?").join(", ");
      await connection.query(
        `
        SELECT id
        FROM stock
        WHERE company_id = ?
          AND barcode IN (${placeholders})
        FOR UPDATE
        `,
        [access.companyScope, ...barcodes]
      );
    }

    await connection.query(
      `
      SELECT tm.id
      FROM invoice_transaction_link itl
      INNER JOIN transaction_master tm
        ON tm.id = itl.transaction_id
       AND tm.company_id = itl.company_id
      WHERE itl.company_id = ?
        AND itl.invoice_no = ?
      FOR UPDATE
      `,
      [access.companyScope, invoiceNumber]
    );

    const cancelResult = await cancelSimpleUnpaidSaleInvoice({
      connection,
      req,
      access,
      companyId: access.companyScope,
      invoiceNumber,
      reason
    });

    if (!cancelResult.ok) {
      await connection.rollback();
      return res.status(cancelResult.status || 409).json(cancelResult.body);
    }

    await connection.commit();
    return res.status(cancelResult.status || 200).json(cancelResult.body);
  } catch (error) {
    if (connection) {
      try {
        await connection.rollback();
      } catch (_) {}
    }

    console.error("Sale cancellation error:", error);
    return res.status(500).json({
      success: false,
      message: "Sale cancellation failed",
      error: getErrorDetail(error)
    });
  } finally {
    if (connection) connection.release();
  }
});

app.delete("/sales-history/:invoiceNumber", authMiddleware, checkRole(["SUPERADMIN", "OWNER"]), async (req, res) => {
  let connection;

  try {
    const invoiceNumber = String(req.params.invoiceNumber || "").trim();
    const access = await resolveAccessContext(req, {
      requireActingUser: true,
      requireCompanyScope: true,
      allowSuperAdminAll: false
    });

    if (!access.ok) {
      return sendAccessError(res, access);
    }

    if (!invoiceNumber) {
      return res.status(400).json({
        success: false,
        message: "Invoice number is required"
      });
    }

    const companyId = access.companyScope;
    const deletedBy = access.actingUserId ?? getRequestedUserId(req) ?? null;
    const deleteReason = String(req.body?.reason || req.query?.reason || "").trim().slice(0, 255);
    connection = await pool.getConnection();
    await connection.beginTransaction();

    const [saleRows] = await connection.query(
      `
      SELECT *
      FROM sales_history
      WHERE invoice_number = ? AND company_id = ? AND COALESCE(is_deleted, 0) = 0
      ORDER BY id DESC
      LIMIT 1
      `,
      [invoiceNumber, companyId]
    );

    if (!saleRows.length) {
      await connection.rollback();
      return res.status(404).json({
        success: false,
        message: "Sale record not found"
      });
    }

    await writeAuditLogSafe(connection, req, {
      companyId,
      userId: deletedBy,
      actionType: "DELETE",
      entityType: "SALE",
      entityId: invoiceNumber,
      beforeData: {
        sale: saleRows[0]
      },
      afterData: {
        deleted: true,
        invoiceNumber,
        deletedBy,
        deleteReason
      }
    });

    await connection.query(
      `
      UPDATE sales_items
      SET is_deleted = 1,
          deleted_at = NOW(),
          deleted_by = ?,
          delete_reason = ?
      WHERE invoice_number = ? AND company_id = ?
      `,
      [deletedBy, deleteReason, invoiceNumber, companyId]
    );

    await connection.query(
      `
      UPDATE sales_history
      SET is_deleted = 1,
          deleted_at = NOW(),
          deleted_by = ?,
          delete_reason = ?
      WHERE invoice_number = ? AND company_id = ?
      `,
      [deletedBy, deleteReason, invoiceNumber, companyId]
    );

    await connection.commit();
    return res.json({
      success: true,
      message: "Sale deleted successfully"
    });
  } catch (error) {
    if (connection) {
      try {
        await connection.rollback();
      } catch (_) {}
    }
    console.error("Permanent sales delete error:", error);
    return res.status(500).json({
      success: false,
      message: "Permanent delete failed"
    });
  } finally {
    if (connection) connection.release();
  }
});

